- [ ] **Step 1: Write `ch422g.h`**

```cpp
#pragma once
#include <stdint.h>

// Minimal CH422G IO expander driver, vendored to keep the dependency tree
// copyleft-free and to avoid pulling in ESP_IOExpander for four register
// writes.
//
// The chip has no register pointer: each I2C *address* is itself a register
// (see the CH422G_* defines in board.h). A write is therefore a one-byte
// transaction to the register's own address, not the usual
// address-then-register-then-value.
//
// Register map confirmed against two independent implementations that agree
// exactly: Espressif's ESP32_IO_Expander and ESPHome's ch422g component.

// Probe and configure IO0-7 as outputs. Returns false if the chip does not
// ACK. Safe to call once from board_init().
bool ch422g_init(void);

// Drive EXIO n (0..7) high or low, preserving the other bits.
void ch422g_set(uint8_t exio, bool high);

// Escape hatch for bring-up instrumentation and OC-pin access.
bool ch422g_write_raw(uint8_t reg_addr, uint8_t value);

// Current cached output byte (what was last written to WR_IO).
uint8_t ch422g_io_state(void);
```

- [ ] **Step 2: Write `ch422g.cpp`**

```cpp
#include "ch422g.h"
#include "board.h"
#include <Arduino.h>
#include <Wire.h>

// WR_IO powers up at 0xFF (all outputs HIGH). Seeding the cache with the
// hardware default matters: the GT911 therefore boots OUT of reset, and a
// reset pulse must actively drive EXIO1 low rather than merely releasing it.
static uint8_t io_state = 0xFF;

bool ch422g_write_raw(uint8_t reg_addr, uint8_t value) {
    Wire.beginTransmission(reg_addr);
    Wire.write(value);
    return Wire.endTransmission() == 0;
}

bool ch422g_init(void) {
    // WR_SET defaults to 0x01 (IO_OE already set), so this write is
    // belt-and-braces rather than load-bearing — but it makes the state
    // explicit after a warm reset that left the chip in some other mode.
    if (!ch422g_write_raw(CH422G_WR_SET, CH422G_MODE_IO_OE)) {
        Serial.println("CH422G: no ACK on WR_SET (0x24) — expander missing?");
        return false;
    }
    if (!ch422g_write_raw(CH422G_WR_IO, io_state)) {
        Serial.println("CH422G: no ACK on WR_IO (0x38)");
        return false;
    }
    Serial.printf("CH422G OK (WR_IO=0x%02X)\n", io_state);
    return true;
}

void ch422g_set(uint8_t exio, bool high) {
    if (exio > 7) return;
    if (high) io_state |= (uint8_t)(1u << exio);
    else      io_state &= (uint8_t)~(1u << exio);
    ch422g_write_raw(CH422G_WR_IO, io_state);
}

uint8_t ch422g_io_state(void) { return io_state; }
```

- [ ] **Step 3: Rewrite `board_init.cpp` with the I²C scan (rung 1)**

```cpp
#include "board.h"
#include "ch422g.h"
#include <Arduino.h>
#include <Wire.h>

// Per-board pre-init. Everything here must complete before
// display_hal_init(), because EXIO2 gates the backlight and EXIO1 gates the
// touch controller's reset.

// TEMPORARY bring-up instrumentation — removed in Task 10. Prints every
// ACKing I2C address so the CH422G (0x24/0x38/0x23/0x26 respond as
// addresses, not as one device) and the GT911 (0x5D or 0x14) can be
// identified before a single pixel is drawn.
static void i2c_scan(void) {
    Serial.println("I2C scan:");
    for (uint8_t addr = 0x08; addr < 0x78; ++addr) {
        Wire.beginTransmission(addr);
        if (Wire.endTransmission() == 0) Serial.printf("  ACK 0x%02X\n", addr);
    }
    Serial.println("I2C scan done");
}

extern "C" void board_init(void) {
    Wire.begin(IIC_SDA, IIC_SCL);
    delay(50);            // let the expander and touch controller settle

    i2c_scan();           // TEMPORARY — remove in Task 10

    ch422g_init();

    // Backlight on. Task 5 takes ownership of this line for idle blanking.
    ch422g_set(EXIO_LCD_BL, true);

    // Touch reset pulse. WR_IO powers up at 0xFF so the GT911 is already out
    // of reset — drive EXIO1 low first or the controller is never reset.
    // INT is held low across the release to select address 0x5D.
    pinMode(TP_INT, OUTPUT);
    digitalWrite(TP_INT, LOW);
    ch422g_set(EXIO_TP_RST, false);
    delay(10);
    ch422g_set(EXIO_TP_RST, true);
    delay(5);
    pinMode(TP_INT, INPUT);
    delay(50);            // GT911 firmware boot
    Serial.println("board_init done");
}
```

